select * from customer_behaviour;

#Q1. What is total revenue generated by Male and Female Customers?
select gender as Gender, SUM(`purchase_amount_(usd)`) as Revenue
from customer_behaviour
group by gender;

#Q2. Which customers uses discount but still spend more than avg purchase amount?
select customer_id, `purchase_amount_(usd)` 
from customer_behaviour
where `purchase_amount_(usd)`>(select avg(`purchase_amount_(usd)`) from customer_behaviour where discount_applied='Yes')